      // ── Flag mode HUD ──
      if (s.flagMode)
        Positioned(
          left: 16, right: 16, bottom: 104,
          child: _FlaggingHud(
            selectedFlag: _selectedFlag,
            onSelectFlag: (f) => setState(() => _selectedFlag = f),
